use crate::Freshness;

pub fn freshness(binary_mtime: Option<i64>, newest_source_mtime: Option<i64>) -> Freshness {
    let (Some(b), Some(s)) = (binary_mtime, newest_source_mtime) else { return Freshness::Unknown };
    let behind = s - b;
    if behind > 0 {
        Freshness::Stale { behind_ms: behind }
    } else {
        Freshness::Fresh
    }
}
